import React, { useState } from 'react';
import { Routes, Route, Navigate, useLocation, useNavigate } from 'react-router-dom';
import Sidebar from '../Sidebar/Sidebar';
import Topbar from '../Topbar/Topbar';
import pageRoutes from '../routes/pageRoutes';

export default function AppLayout({ user, onLogout }) {
  const [collapsed, setCollapsed] = useState(false);
  const [mobileOpen, setMobileOpen] = useState(false);
  const [search, setSearch] = useState('');
  const location = useLocation();
  const navigate = useNavigate();
  const availablePages = pageRoutes.filter(p => p.roles.includes(user.role));
  const currentPage = availablePages.find(page => page.path === location.pathname);
  const activePage = currentPage ? currentPage.name : 'Dashboard';
  const goToPage = (name) => {
    const selected = availablePages.find(page => page.name === name);
    if (selected) { navigate(selected.path); setMobileOpen(false); }
  };
  return <div className={`app-shell ${collapsed ? 'is-collapsed' : ''} ${mobileOpen ? 'mobile-open' : ''}`}>
    {mobileOpen && <button aria-label="Close navigation" className="mobile-scrim" onClick={()=>setMobileOpen(false)} />}
    <Sidebar activePage={activePage} onNavigate={goToPage} collapsed={collapsed} user={user}/>
    <main className="main-area">
      <Topbar onToggle={() => {
        if (window.matchMedia('(max-width: 850px)').matches) setMobileOpen(v=>!v);
        else setCollapsed(v=>!v);
      }} search={search} onSearch={setSearch}/>
      <div className="session-strip"><span className={`role-dot ${user.role}`}></span><span>Signed in as <b>{user.name}</b> · {user.role === 'owner' ? 'Owner access' : 'Employee workspace'}</span><button onClick={onLogout}>Sign out ↗</button></div>
      <div className="page-container">
        <Routes>
          {availablePages.map(({ name, path, component: Page }) => <Route key={path} path={path} element={<Page globalSearch={search} onNavigate={goToPage}/>} />)}
          <Route path="/" element={<Navigate to="/dashboard" replace/>}/>
          <Route path="*" element={<Navigate to="/dashboard" replace/>}/>
        </Routes>
      </div>
      <footer className="footer"><b>RealEstate Pro CRM</b><span>Responsive prototype · Demo data only</span></footer>
    </main>
  </div>;
}
